import{_ as t,o,c as a,a3 as n}from"./chunks/framework.cNy3aYYk.js";const h=JSON.parse('{"title":"Companies duplicate matching and merge (1.5.0) — Production Readiness Audit","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Companies duplicate matching and merge (1.5.0) — Production Readiness Audit | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/deployment/companies-duplicate-merge-1-5-0-production-readiness"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Companies duplicate matching and merge (1.5.0) — Production Readiness Audit | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/deployment/companies-duplicate-merge-1-5-0-production-readiness"}]]},"headers":[],"relativePath":"deployment/companies-duplicate-merge-1-5-0-production-readiness.md","filePath":"deployment/companies-duplicate-merge-1-5-0-production-readiness.md","lastUpdated":1792264712000}'),r={name:"deployment/companies-duplicate-merge-1-5-0-production-readiness.md"};function d(s,e,i,c,l,m){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="companies-duplicate-matching-and-merge-1-5-0-—-production-readiness-audit" tabindex="-1">Companies duplicate matching and merge (1.5.0) — Production Readiness Audit <a class="header-anchor" href="#companies-duplicate-matching-and-merge-1-5-0-—-production-readiness-audit" aria-label="Permalink to &quot;Companies duplicate matching and merge (1.5.0) — Production Readiness Audit&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td><strong>Date</strong></td><td>2026-10-16</td></tr><tr><td><strong>Status</strong></td><td><strong>Go for production</strong> — feature Pest green; headed companies Playwright 8/8 on one demo login</td></tr><tr><td><strong>Scope</strong></td><td>Normalized company identity, import match before create, contact-import and lead-convert reuse, merge of duplicates under <code>companies.delete</code></td></tr><tr><td><strong>Branch</strong></td><td><code>feature/company-duplicate-merge</code> (Backend, Frontend, Docs)</td></tr><tr><td><strong>Catalog</strong></td><td><strong>companies 1.4.0 → 1.5.0</strong></td></tr><tr><td><strong>Companion</strong></td><td><a href="/user-guide/companies">Companies user guide</a> · <a href="/developer-guide/companies">Companies developer guide</a> · <a href="/api/tenant-v1-companies">Companies API</a> · <a href="/changelog/">CHANGELOG</a></td></tr></tbody></table><hr><h2 id="executive-summary" tabindex="-1">Executive summary <a class="header-anchor" href="#executive-summary" aria-label="Permalink to &quot;Executive summary&quot;">​</a></h2><p>Company CSV/XLSX import, contact import, and lead conversion were creating a second company when the name differed only by case, punctuation, or a trailing suffix such as Inc. Companies <strong>1.5.0</strong> stores a non-unique <code>normalized_name</code>, matches that key and a company website/email domain before insert, and lets a user with <strong>delete</strong> merge the extras onto one primary inside a transaction.</p><p><strong>Go / No-Go:</strong> <strong>Go.</strong> No new permissions, no shell/auth/settings redesign, no unique index. Operators merge existing duplicates first; the index stays non-unique on purpose.</p><table tabindex="0"><thead><tr><th>Gate</th><th>Result</th></tr></thead><tbody><tr><td>Platform freeze (no shell/auth/billing redesign)</td><td><strong>Pass</strong></td></tr><tr><td>Identity key: lowercase, trim, collapse spaces, strip punctuation and trailing Inc/LLC/Ltd/Pvt/Co/Corp</td><td><strong>Pass</strong> (Pest)</td></tr><tr><td>Indexed <code>(tenant_id, normalized_name)</code> with backfill; <strong>not</strong> unique</td><td><strong>Pass</strong></td></tr><tr><td>Import matches name, then website/email domain, before create; preview shows matched vs new</td><td><strong>Pass</strong> (Pest + headed Playwright)</td></tr><tr><td>Consumer email domains (gmail, outlook, and the rest of the free-mail list) do not collapse unrelated companies</td><td><strong>Pass</strong> (code review)</td></tr><tr><td>Contact import and lead convert reuse the same key</td><td><strong>Pass</strong> (Pest)</td></tr><tr><td>Merge is one DB transaction, fills only empty fields, moves related records, writes “Merged from …”, soft-deletes duplicates</td><td><strong>Pass</strong> (Pest + headed Playwright)</td></tr><tr><td>Merge routes require <code>companies.delete</code>; other tenants’ ids are rejected</td><td><strong>Pass</strong> (Pest)</td></tr><tr><td>Rollback leaves both companies when a later step fails</td><td><strong>Pass</strong> (Pest)</td></tr><tr><td>Catalog migrate-only bump + CatalogSeeder companion</td><td><strong>Pass</strong> (Pest)</td></tr><tr><td>Create form rejects an empty name and an invalid email before the API call</td><td><strong>Pass</strong> (headed Playwright)</td></tr><tr><td>Merge confirmation lists what moves and which empty fields will be filled</td><td><strong>Pass</strong> (headed Playwright)</td></tr><tr><td>Feature Pest</td><td><strong>Pass</strong> — 35 tests / 210 assertions (duplicate, company import, contact import, company CRUD, catalog bump) plus 6 lead company assertions</td></tr><tr><td>Companies Playwright, headed, one worker</td><td><strong>Pass</strong> — 8/8 (<code>test:e2e:companies:headed</code>)</td></tr></tbody></table><hr><h2 id="security-summary" tabindex="-1">Security summary <a class="header-anchor" href="#security-summary" aria-label="Permalink to &quot;Security summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Control</th><th>Status</th></tr></thead><tbody><tr><td><code>POST /companies/{id}/merge-preview</code> and <code>POST /companies/{id}/merge</code> use <code>can:companies.delete</code></td><td>Pass</td></tr><tr><td>Form request authorizes <code>companies.delete</code> and requires a distinct integer <code>duplicate_ids</code> list</td><td>Pass</td></tr><tr><td>Missing or other-tenant ids return 422 (“could not be found in this workspace”) because of the tenant global scope</td><td>Pass</td></tr><tr><td>Staff without <code>companies.delete</code> receive 403</td><td>Pass</td></tr><tr><td>Soft-delete of duplicates does not write a second activity row onto the archived company</td><td>Pass</td></tr><tr><td>Import identity match still goes through <code>CompanyService::create()</code> / <code>update()</code></td><td>Pass</td></tr><tr><td><code>normalized_name</code> is not mass-assignable, so activity logs do not treat it as a user field</td><td>Pass</td></tr></tbody></table><hr><h2 id="findings-disposition" tabindex="-1">Findings disposition <a class="header-anchor" href="#findings-disposition" aria-label="Permalink to &quot;Findings disposition&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Severity</th><th>Item</th><th>Disposition</th></tr></thead><tbody><tr><td><strong>F1</strong></td><td>Medium</td><td>Company create accepted an invalid email in the browser and only failed after the API returned 422</td><td><strong>Fixed</strong> — form uses the same “Enter a valid email” rule as Leads. Headed test submits <code>not-an-email</code> and stays on the form</td></tr><tr><td><strong>F2</strong></td><td>Low</td><td>Merge confirmation listed empty fields as raw keys (<code>phone</code>)</td><td><strong>Fixed</strong> — dialog shows Email, Phone, Website, Industry, Address, Source</td></tr><tr><td><strong>I1</strong></td><td>Info</td><td>No unique index on <code>normalized_name</code></td><td><strong>Accepted</strong> — existing duplicates must be merged before a unique index is safe</td></tr><tr><td><strong>I2</strong></td><td>Info</td><td>Two different names that share a company email or website domain match as one company</td><td><strong>Accepted</strong> — that is the identity rule. Free-mail domains are excluded</td></tr><tr><td><strong>I3</strong></td><td>Info</td><td>Full <code>php artisan test --compact</code> was not re-run for this audit</td><td><strong>Accepted for this change</strong> — the companies, contact-import, lead-convert, and catalog suites that this change touches passed</td></tr></tbody></table><hr><h2 id="headed-browser-coverage" tabindex="-1">Headed browser coverage <a class="header-anchor" href="#headed-browser-coverage" aria-label="Permalink to &quot;Headed browser coverage&quot;">​</a></h2><p>One demo login for <code>e2e/tests/companies/companies.duplicate-merge.headed.spec.ts</code>, then the rest of <code>e2e/tests/companies</code> on the same Playwright project (<code>--headed --workers=1</code>):</p><ol><li>Sign in once and open Companies</li><li>Submit an empty name (<strong>Name is required</strong>) and an invalid email (<strong>Enter a valid email</strong>)</li><li>Create <code>Acme {suffix} Inc</code> and <code>ACME, {suffix}, Inc.</code>, add a note on the duplicate, see <strong>Possible duplicate</strong></li><li>Open the merge dialog, confirm it lists the note and the phone fill, cancel, then merge</li><li>Primary shows the moved note, the filled phone, and “Merged from …”; the duplicate is gone from the active directory</li><li>Import preview shows <strong>Matched existing company</strong> and <strong>New company</strong>, then the import completes and the new company is in the directory</li><li>Existing follow-ups, import history, and notes workflow specs</li></ol><p>Result on 2026-10-16: <strong>8 passed</strong>.</p><hr><h2 id="change-inventory" tabindex="-1">Change inventory <a class="header-anchor" href="#change-inventory" aria-label="Permalink to &quot;Change inventory&quot;">​</a></h2><h3 id="backend" tabindex="-1">Backend <a class="header-anchor" href="#backend" aria-label="Permalink to &quot;Backend&quot;">​</a></h3><ul><li><code>CompanyName</code>, <code>CompanyIdentityMatcher</code>, <code>CompanyMergeService</code></li><li><code>companies.normalized_name</code> (nullable, indexed with <code>tenant_id</code>, backfilled)</li><li>Catalog migration <strong>companies 1.4.0 → 1.5.0</strong></li><li>Import preview counts <code>matched_existing_companies</code> and <code>new_companies</code></li><li>Routes <code>merge-preview</code> and <code>merge</code></li><li>Pest: <code>CompanyDuplicateTest</code>, <code>CompaniesModuleVersion150BumpTest</code></li></ul><h3 id="frontend" tabindex="-1">Frontend <a class="header-anchor" href="#frontend" aria-label="Permalink to &quot;Frontend&quot;">​</a></h3><ul><li>Directory <strong>Possible duplicate</strong> badge</li><li>Company page hint and <strong>Merge duplicates</strong> confirmation</li><li>Import preview chips <strong>New company</strong> / <strong>Matched existing company</strong></li><li>Create-form email format check</li><li>Playwright: <code>e2e/tests/companies/companies.duplicate-merge.headed.spec.ts</code>, <code>npm run test:e2e:companies:headed</code></li></ul><h3 id="docs" tabindex="-1">Docs <a class="header-anchor" href="#docs" aria-label="Permalink to &quot;Docs&quot;">​</a></h3><ul><li>User, developer, and API guides</li><li>This audit</li></ul><hr><h2 id="catalog-version-path" tabindex="-1">Catalog version path <a class="header-anchor" href="#catalog-version-path" aria-label="Permalink to &quot;Catalog version path&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Migration</th><th>Effect</th></tr></thead><tbody><tr><td><code>2026_10_15_232609_add_normalized_name_to_companies_table</code></td><td>Adds nullable <code>normalized_name</code>, index <code>(tenant_id, normalized_name)</code>, backfills existing rows</td></tr><tr><td><code>2026_10_15_232611_bump_companies_module_version_for_duplicate_merge</code></td><td>companies <strong>1.4.0 → 1.5.0</strong></td></tr></tbody></table><p>Production: <strong>migrate only</strong>. Do <strong>not</strong> <code>db:seed</code> on upgrade. <code>CatalogSeeder</code> already records companies <strong>1.5.0</strong> for fresh installs.</p><p>The bump does not install Companies into workspaces that do not already have it.</p><hr><h2 id="deploy-sequence-migrate-first" tabindex="-1">Deploy sequence (migrate-first) <a class="header-anchor" href="#deploy-sequence-migrate-first" aria-label="Permalink to &quot;Deploy sequence (migrate-first)&quot;">​</a></h2><ol><li>Deploy <strong>Backend</strong> → <code>php artisan migrate --force</code></li><li>Confirm <code>modules.version</code> for <code>companies</code> is <strong>1.5.0</strong></li><li>Deploy <strong>Frontend</strong> after a production build; hard-refresh the SPA</li><li>Deploy <strong>Docs</strong></li><li>Staging smoke (below)</li></ol><p>No new env vars. No new queues. Company import still uses the <code>imports</code> queue.</p><p>Do <strong>not</strong> add a unique index in this release.</p><hr><h2 id="staging-smoke" tabindex="-1">Staging smoke <a class="header-anchor" href="#staging-smoke" aria-label="Permalink to &quot;Staging smoke&quot;">​</a></h2><ul><li>[ ] Create “Acme Inc” and “ACME, Inc.” — the second page shows a possible duplicate</li><li>[ ] Submit a company with email <code>not-an-email</code> — the form shows <strong>Enter a valid email</strong> and does not create a row</li><li>[ ] Import a CSV whose name is “Acme Inc” when “Acme Inc” already exists — preview says matched existing, and skip mode does not create a second row</li><li>[ ] Merge the duplicate — contacts/notes stay on the primary, empty fields fill, the duplicate disappears from Active only</li><li>[ ] A user without <code>companies.delete</code> does not see <strong>Merge duplicates</strong></li></ul><hr><h2 id="rollback" tabindex="-1">Rollback <a class="header-anchor" href="#rollback" aria-label="Permalink to &quot;Rollback&quot;">​</a></h2><ul><li>Code rollback is safe. <code>normalized_name</code> can remain; older code ignores it.</li><li>Migration <code>down</code> drops the column and sets the catalog back to <strong>1.4.0</strong>. Do not roll back after operators have merged companies if you still need the archived duplicates’ history on the primary — the moved foreign keys are already on the primary and are not reversed by the migration.</li></ul>',42)])])}const g=t(r,[["render",d]]);export{h as __pageData,g as default};
